"""Whole package-only gateway pwd import regression with typed inert IO boundaries."""
import ast,hashlib,json,os,subprocess,sys,unittest
from pathlib import Path
FIXTURES=Path(__file__).with_name('fixtures')/'windows_d32_gateway_imports'
PINS={'gateway.after.py.txt': {'bytes': 44112, 'sha256': 'e409c03ea3accccf0b16ea8653217e166b19fc372ece2184fc8bb48ab19c54bd'}, 'gateway.before.py.txt': {'bytes': 44101, 'sha256': '8bf67e82925b04c58a429cea38041510e0566ceb61908aa9e473677e451fbf18'}, 'metadata.public.json': {'bytes': 894, 'sha256': '1af7bcf7aa6f73c2a9b6a5c4765068b6429208a9d3d2d0a06ec9d22640142a97'}}
def read_fixture(name):
    pin=PINS[name]
    with(FIXTURES/name).open('rb')as stream:raw=stream.read(pin['bytes']+1)
    if len(raw)!=pin['bytes']or hashlib.sha256(raw).hexdigest()!=pin['sha256']:raise ValueError('gateway_fixture_pin')
    return raw
WORKER='import builtins,contextlib,hashlib,io,json,os,shlex,stat,sys,tempfile,types\nfrom pathlib import Path\nsource=json.loads(sys.stdin.buffer.read(50000));events=[];output=io.StringIO();real_import=builtins.__import__;real_os=os;real_text=Path.read_text\ncorr=\'11111111-2222-4333-8444-555555555555\';home=\'/synthetic/owned-home\';config=home+\'/.ssh/config\';key=home+\'/.ssh/inert\';digest=hashlib.sha256(source.encode()).hexdigest()\nheader=b\'{"passphrase":"synthetic-inert-passphrase"}\\nowned-package-prefix\'\nreadfd,writefd=os.pipe();os.write(writefd,header);os.close(writefd);stream=os.fdopen(readfd,\'rb\',buffering=0)\nowned_fds=set();children=0\nfake_pwd=types.SimpleNamespace(getpwuid=lambda uid:types.SimpleNamespace(pw_dir=home)if uid==1000 else (_ for _ in ()).throw(AssertionError(\'FOREIGN_UID\')))\nhome_stat=types.SimpleNamespace(st_dev=1,st_ino=2,st_mode=stat.S_IFDIR|0o700,st_uid=1000,st_gid=1000,st_nlink=1,st_size=0,st_mtime_ns=3,st_ctime_ns=4)\nwith tempfile.TemporaryDirectory(prefix=\'owned-d32-gateway-\')as td:\n root=Path(td)/(\'package-\'+corr);root.mkdir(mode=0o700)\n accepted=str(root/\'inner-original-accepted.private.json\')\n def lstat(path):\n  if str(path)!=home:raise AssertionError(\'FOREIGN_LSTAT\')\n  events.append(\'home_lstat\');return home_stat\n def open_owned(path,flags,mode=0o777,**kwargs):\n  if str(path)!=accepted or flags!=(os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW)or mode!=0o600 or kwargs:raise AssertionError(\'FOREIGN_OPEN\')\n  fd=real_os.open(path,flags,mode);owned_fds.add(fd);return fd\n def read_owned(fd,count):\n  if fd!=readfd:raise AssertionError(\'FOREIGN_READ\')\n  return real_os.read(fd,count)\n def write_owned(fd,value):\n  if fd not in owned_fds:raise AssertionError(\'FOREIGN_WRITE\')\n  return real_os.write(fd,value)\n def sync_owned(fd):\n  if fd not in owned_fds:raise AssertionError(\'FOREIGN_FSYNC\')\n  return real_os.fsync(fd)\n def close_owned(fd):\n  if fd not in owned_fds:raise AssertionError(\'FOREIGN_CLOSE\')\n  owned_fds.remove(fd);return real_os.close(fd)\n def block_owned(fd,value):\n  if fd!=readfd:raise AssertionError(\'FOREIGN_SET_BLOCKING\')\n  return real_os.set_blocking(fd,value)\n fake_os=types.SimpleNamespace(**{name:getattr(real_os,name)for name in (\'O_RDONLY\',\'O_RDWR\',\'O_WRONLY\',\'O_CREAT\',\'O_EXCL\',\'O_NOFOLLOW\',\'O_DIRECTORY\',\'O_NONBLOCK\',\'fsencode\')})\n fake_os.getuid=lambda:1000;fake_os.lstat=lstat;fake_os.path=types.SimpleNamespace(lexists=lambda path:True if str(path)==key else (_ for _ in ()).throw(AssertionError(\'FOREIGN_KEY_PATH\')))\n fake_os.statvfs=lambda path:types.SimpleNamespace(f_bavail=262144,f_frsize=4096)if path==\'/tmp\'else (_ for _ in ()).throw(AssertionError(\'FOREIGN_DISK\'))\n fake_os.open=open_owned;fake_os.read=read_owned;fake_os.write=write_owned;fake_os.fsync=sync_owned;fake_os.close=close_owned;fake_os.set_blocking=block_owned\n def route(argv,**kwargs):\n  expected=[\'ssh\',\'-T\',\'-F\',config,\'-S\',\'none\',\'-o\',\'ControlMaster=no\',\'-o\',\'ControlPersist=no\',\'-o\',\'ClearAllForwardings=yes\',\'-o\',\'PermitLocalCommand=no\',\'-o\',\'UpdateHostKeys=no\',\'-o\',\'ProxyCommand=none\',\'-G\',\'archlinux\']\n  if argv!=expected or kwargs!={\'capture_output\':True,\'timeout\':5}:raise AssertionError(\'FOREIGN_SUBPROCESS\')\n  events.append(\'ssh_G\');return types.SimpleNamespace(returncode=0,stdout=b\'identityfile ~/.ssh/inert\\n\',stderr=b\'\')\n def forbidden(*args,**kwargs):raise AssertionError(\'NATIVE_CHILD_OR_COMMAND\')\n fake_subprocess=types.SimpleNamespace(run=route,Popen=forbidden,SubprocessError=RuntimeError)\n fake_sys=types.SimpleNamespace(argv=[\'fixed-public-gateway\',corr,config,\'archlinux\',digest],stdin=types.SimpleNamespace(buffer=stream))\n def importer(name,*args,**kwargs):\n  if name==\'pwd\':events.append(\'pwd_import\');return fake_pwd\n  if name==\'os\':return fake_os\n  if name==\'subprocess\':return fake_subprocess\n  if name==\'sys\':return fake_sys\n  return real_import(name,*args,**kwargs)\n namespace={\'__name__\':\'owned_public_gateway\',\'__builtins__\':{**vars(builtins),\'__import__\':importer}}\n def boot(path,*args,**kwargs):\n  if str(path)!=\'/proc/sys/kernel/random/boot_id\':raise AssertionError(\'FOREIGN_HOST_READ\')\n  events.append(\'synthetic_boot\');return \'ffaa02f2-49e2-4672-851c-d5a5c15f4a58\\n\'\n def file_pin(path,*,body=False,private=False):\n  if (str(path),body,private)not in ((config,True,False),(key,False,True)):raise AssertionError(\'FOREIGN_FILE_PIN\')\n  events.append(\'file_pin\');return {\'generation\':[1,2,stat.S_IFREG|0o600,1000,1000,1,12,3,4],\'parents\':[],\'bytes\':12,\'sha256\':\'a\'*64,\'unsupportedConfigDirectives\':False}\n image={\'state\':\'FIXED_D32_PACKAGE_IMAGE_VALIDATED\',\'archiveSha256\':\'753cd6487892dd1dce09930b09f6bce8052d3f077bbb7a11acf1bb6cd1c9ebe2\',\'regularFiles\':154,\'imageBytes\':211331924,\'joinedImageClosings\':2,\'launcherExecuted\':False,\'globalInstall\':False,\'profileChanged\':False}\n class Custody:\n  def __init__(self):self.raw={\'stdout\':bytearray(json.dumps(image).encode()),\'tty\':bytearray()};self.child=types.SimpleNamespace(pid=12345);self.closed=False\n  def observe(self,seconds):\n   if seconds!=90:raise AssertionError(\'FOREIGN_OBSERVATION\')\n   self.closed=True;return {\'pid\':12345,\'returnCode\':0,\'complete\':True,\'timeout\':False,\'refusal\':None,\'credentialSent\':True}\n  def finish_naturally(self):self.closed=True\n def receive(stream_arg,correlation,prefix=b\'\'):\n  if stream_arg is not stream or correlation!=corr or prefix!=b\'owned-package-prefix\':raise AssertionError(\'FOREIGN_RECEIVE\')\n  events.append(\'receive\');fd=real_os.open(root/\'archive.inert\',real_os.O_RDWR|real_os.O_CREAT|real_os.O_EXCL,0o600);owned_fds.add(fd)\n  return fd,{\'bytes\':141244908,\'sha256\':image[\'archiveSha256\'],\'generation9\':[1,2,stat.S_IFREG|0o600,1,1000,1000,141244908,3,4],\'namedEqual\':True,\'eof\':True,\'correlation\':corr}\n def start(argv,secret,keys,archive_fd):\n  if secret!=b\'synthetic-inert-passphrase\' or set(keys)!={key} or archive_fd not in owned_fds:raise AssertionError(\'FOREIGN_START\')\n  if argv[:7]!=[\'ssh\',\'-T\',\'-F\',config,\'-S\',\'none\',\'-o\']or \'ProxyCommand=none\'not in argv or argv[-2]!=\'archlinux\':raise AssertionError(\'FOREIGN_INNER_ROUTE\')\n  command=shlex.split(argv[-1]);assert command[:4]==[\'python3\',\'-I\',\'-B\',\'-c\'] and len(command)==5\n  events.append(\'start_boundary\');return Custody()\n Path.read_text=boot\n try:\n  exec(compile(source,\'whole-public-package-gateway\',\'exec\'),namespace)\n  namespace.update(_DECODED_SOURCE_SHA=digest,ROOT_PREFIX=str(Path(td)/\'package-\'),file_pin=file_pin,receive_fixed_package=receive,start_fixed=start)\n  try:\n   with contextlib.redirect_stdout(output):code=namespace[\'remote_main\']()\n   result={\'state\':\'PASS\',\'returnCode\':code,\'consumerJSON\':json.loads(output.getvalue())}\n  except NameError as error:result={\'state\':\'RED\',\'errorClass\':\'NameError\',\'identifier\':error.name}\n  result.update(events=events,nativeChildren=children,acceptedRecordExists=root.joinpath(\'inner-original-accepted.private.json\').exists(),archiveReceived=events.count(\'receive\'),startBoundaryCalls=events.count(\'start_boundary\'),sourceSHA=digest)\n finally:\n  Path.read_text=real_text;stream.close()\n  for fd in tuple(owned_fds):real_os.close(fd);owned_fds.remove(fd)\n print(json.dumps(result,sort_keys=True))\n'
@unittest.skipUnless(os.name=='posix'and hasattr(os,'O_NOFOLLOW'),'requires isolated owned POSIX child')
class WindowsD32GatewayImportsTests(unittest.TestCase):
    def setUp(self):
        before=read_fixture('gateway.before.py.txt');after=read_fixture('gateway.after.py.txt')
        self.assertEqual(b'import pwd\n'+before,after)
        self.assertEqual(ast.dump(ast.parse(before),include_attributes=False),ast.dump(ast.Module(ast.parse(after).body[1:],type_ignores=[]),include_attributes=False))
        metadata=json.loads(read_fixture('metadata.public.json'));self.assertIs(metadata['containsCredentialValues'],False);self.assertIs(metadata['containsProtectedAndroidProgramme'],False);self.assertIs(metadata['nativeClaim'],False);self.assertIs(metadata['rawTracebackExported'],False)
    def control(self,name):
        env=dict(os.environ);env.pop('DYLD_INSERT_LIBRARIES',None)
        result=subprocess.run([sys.executable,'-I','-B','-c',WORKER],input=json.dumps(read_fixture(name).decode()).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=10,env=env)
        self.assertEqual(0,result.returncode,result.stderr.decode('utf-8','replace'));self.assertFalse(result.stderr);self.assertLessEqual(len(result.stdout),16384)
        return json.loads(result.stdout)
    def test_actual_before_NameError_pwd_precedes_archive_receive_and_start(self):
        value=self.control('gateway.before.py.txt');self.assertEqual('RED',value['state']);self.assertEqual('NameError',value['errorClass']);self.assertEqual('pwd',value['identifier'])
        self.assertEqual(1,value['events'].count('ssh_G'));self.assertNotIn('pwd_import',value['events']);self.assertEqual(0,value['archiveReceived']);self.assertEqual(0,value['startBoundaryCalls']);self.assertEqual(0,value['nativeChildren']);self.assertFalse(value['acceptedRecordExists'])
    def test_exact_pwd_import_fix_reaches_complete_package_consumer_JSON(self):
        value=self.control('gateway.after.py.txt');self.assertEqual('PASS',value['state']);self.assertEqual(0,value['returnCode']);self.assertIn('pwd_import',value['events']);self.assertEqual(4,value['events'].count('ssh_G'))
        self.assertEqual(1,value['archiveReceived']);self.assertEqual(1,value['startBoundaryCalls']);self.assertEqual(0,value['nativeChildren']);self.assertTrue(value['acceptedRecordExists'])
        data=value['consumerJSON'];self.assertEqual('observed',data['state']);self.assertEqual(1000,data['gateway']['uid']);self.assertEqual('ffaa02f2-49e2-4672-851c-d5a5c15f4a58',data['gateway']['boot']);self.assertEqual(154,data['image']['regularFiles']);self.assertEqual(211331924,data['image']['imageBytes']);self.assertEqual('753cd6487892dd1dce09930b09f6bce8052d3f077bbb7a11acf1bb6cd1c9ebe2',data['image']['archiveSha256'])
        for flag in ('nativeActionAllowed','replayAllowed','appOrGuestCommands','journalAccess','leaseChanged','configuredCliChanged'):self.assertIs(data[flag],False)
        for flag in ('launcherExecuted','globalInstall','profileChanged'):self.assertIs(data['image'][flag],False)
if __name__=='__main__':unittest.main()
